package dev.colonyhorizons.qa.outpost;
import dev.colonyhorizons.remote.*;
import dev.colonyhorizons.remote.RemoteModels.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.neoforged.neoforge.gametest.PrefixGameTestTemplate;
import java.nio.file.Path;
import java.util.*;

@PrefixGameTestTemplate(false)
public final class FoundingFlowTests {
 @GameTest(template="empty",templateNamespace="colonyhorizons",timeoutTicks=4000)
 public static void approved_founding_flow(GameTestHelper h){h.runAfterDelay(40,()->{var rows=new ArrayList<ProbeResult>();try{
  var l=h.getLevel();String phase=System.getProperty("colonyhorizons.probePhase","seed");if(!phase.equals("seed")){verifyReload(h,rows,phase);return;}var stock=new HashMap<ItemKey,Integer>();stock.put(new ItemKey(new ItemStack(com.minecolonies.api.blocks.ModBlocks.blockHutBuilder)),1);stock.put(new ItemKey(new ItemStack(com.minecolonies.api.blocks.ModBlocks.blockHutLumberjack)),2);stock.put(new ItemKey(new ItemStack(com.minecolonies.api.blocks.ModBlocks.blockHutHome)),4);stock.put(new ItemKey(new ItemStack(Items.DIRT)),5);stock.put(new ItemKey(new ItemStack(Items.BREAD)),16);stock.put(new ItemKey(new ItemStack(Items.STONE_AXE)),3);stock.put(new ItemKey(new ItemStack(Items.STONE_PICKAXE)),1);stock.put(new ItemKey(new ItemStack(Items.STONE_SHOVEL)),1);stock.put(new ItemKey(new ItemStack(Items.OAK_SAPLING)),16);
  var allowance=new HashMap<>(stock);var reserves=new HashMap<ItemKey,Integer>();boolean needs=System.getProperty("colonyhorizons.foundationSuite").equals("MayorNeeds");boolean mayorSupply=System.getProperty("colonyhorizons.foundationSuite").startsWith("MayorSupply");if(needs||mayorSupply){allowance.put(new ItemKey(new ItemStack(Items.BREAD)),40);reserves.put(new ItemKey(new ItemStack(Items.BREAD)),16);}
  if(needs)allowance.put(new ItemKey(new ItemStack(Items.STONE_AXE)),5);
  var env=new RemoteTestEnvironment(l,1024,new Budget(allowance,reserves));var id=env.draft.id();var data=RemoteDevelopmentData.get(l);
  h.assertTrue(RemoteFoundingService.bootstrapBill(l,id).equals(stock),"Server bootstrap includes finite huts, supports, food, tools and saplings");
  var bp=com.ldtteam.structurize.storage.StructurePacks.getBlueprint("Arcology Horizons","fundamentals/builder1.blueprint",l.registryAccess());com.minecolonies.api.blocks.ModBlocks.blockHutBuilder.setup(env.owner,l,env.home.center(),bp,com.ldtteam.structurize.api.RotationMirror.NONE,true,"Arcology Horizons","fundamentals/builder1.blueprint");
  var hut=(com.minecolonies.core.tileentities.TileEntityColonyBuilding)l.getBlockEntity(env.home.center());
  h.assertTrue(!RemoteFoundingService.approve(env.owner,id,0).blockers().isEmpty()&&data.find(id).orElseThrow().phase()==Phase.PROPOSED&&!data.hasClaimJournal(id),"Shortage before any land or inventory mutation");pass(rows,"shortage_before_claims");
  int slot=0;for(var e:stock.entrySet()) {int rest=e.getValue();while(rest>0){int count=Math.min(rest,e.getKey().stack().getMaxStackSize());hut.getInventory().setStackInSlot(slot++,e.getKey().stack().copyWithCount(count));rest-=count;}}if(needs||mayorSupply)hut.getInventory().setStackInSlot(slot++,new ItemStack(Items.BREAD,40));if(needs){hut.getInventory().setStackInSlot(slot++,new ItemStack(Items.STONE_AXE));hut.getInventory().setStackInSlot(slot,new ItemStack(Items.STONE_AXE));}hut.setChanged();
  h.assertTrue(RemoteFoundingService.approve(env.owner,id,0).blockers().isEmpty(),"Approved finite founding");h.assertTrue(data.foundingManaged(id)&&data.find(id).orElseThrow().phase()==Phase.STAGING,"Durable managed staging");pass(rows,"approved_finite_staging");
  var homeBuilder=env.home.colony().getServerBuildingManager().getBuilding(env.home.center()).getFirstModuleOccurance(com.minecolonies.core.colony.buildings.modules.WorkerBuildingModule.class);
  var founder=env.home.colony().getCitizenManager().getCivilian(env.draft.request().citizenIds().get(1));h.assertTrue(!homeBuilder.assignCitizen(founder)&&founder.getJob()==null,"Native hiring must respect the approved founding party");pass(rows,"reserved_founder_not_hired_home");
  var originalId=founder.getUUID();var originalEntity=founder.getEntity().orElseThrow();var identity=com.minecolonies.core.colony.CitizenData.class.getDeclaredField("uuid");identity.setAccessible(true);boolean rejected=false;
  try{var replacement=UUID.randomUUID();identity.set(founder,replacement);originalEntity.setUUID(replacement);try{FoundingTravel.review(env.owner,id);}catch(IllegalArgumentException|IllegalStateException expected){rejected=true;}}
  finally{identity.set(founder,originalId);originalEntity.setUUID(originalId);}
  h.assertTrue(rejected,"Reused native citizen number cannot replace an approved original");pass(rows,"approved_identity_locked");
  h.assertTrue(!RemoteFoundingService.approve(env.owner,id,0).blockers().isEmpty(),"Stale repeat refused");for(int i=0;i<hut.getInventory().getSlots();i++)h.assertTrue(hut.getInventory().getStackInSlot(i).isEmpty()||needs&&hut.getInventory().getStackInSlot(i).is(Items.STONE_AXE)||(needs||mayorSupply)&&hut.getInventory().getStackInSlot(i).is(Items.BREAD)&&hut.getInventory().getStackInSlot(i).getCount()==40,"Exactly one withdrawal");pass(rows,"stale_approval_inert");
  RemoteFoundingService.advance(l,id);h.assertTrue(data.anchorReceipts(id).isEmpty(),"Offline Home owner pauses placement");pass(rows,"offline_founding_paused");
  var owner=RemoteActivityTests.loginAtHome(env);RemoteActivityService.tick(l);
  h.runAfterDelay(40,()->{try{
   for(int i=0;i<8;i++){var result=RemoteFoundingService.advance(l,id);h.assertTrue(result.blockers().isEmpty(),"Native founding step: "+result.blockers());}
   h.assertTrue(data.anchorReceipts(id).size()==7&&data.journey(id).orElseThrow().state()==FoundingTravel.State.IN_TRANSIT,"Paid huts precede original-party travel");pass(rows,"paid_staging_before_travel");
   while(data.journey(id).orElseThrow().remainingTicks()>0){l.getServer().getWorldData().overworldData().setGameTime(l.getGameTime()+20);FoundingTravel.reconcile(l,id);}
   var packed=env.home.colony().getCitizenManager().getCivilian(env.draft.request().mayorId()).getInventory();var old=new ArrayList<ItemStack>();for(int i=0;i<packed.getSlots();i++){old.add(packed.getStackInSlot(i).copy());packed.setStackInSlot(i,new ItemStack(Items.STONE,64));}
   h.assertTrue(!RemoteFoundingService.advance(l,id).blockers().isEmpty()&&data.starterDelivery(id).isEmpty()&&FoundingPlacement.remaining(l,id).equals(FoundingSupplies.bill()),"Full founder keeps entire starter batch in custody");for(int i=0;i<old.size();i++)packed.setStackInSlot(i,old.get(i));pass(rows,"full_starter_inventory_waits");
   h.assertTrue(RemoteFoundingService.advance(l,id).stage().equals("Founders arrived"),"Ready for local appointment, not falsely operating");h.assertTrue(env.home.colony().getCitizenManager().getCitizens().size()==4&&owner.blockPosition().closerThan(env.home.center(),3),"Original party, owner still Home");pass(rows,"founders_arrive_home_owner");
   var totals=new HashMap<Item,Integer>();for(int citizenId:env.draft.request().citizenIds()){var inventory=env.home.colony().getCitizenManager().getCivilian(citizenId).getInventory();int food=0;for(int i=0;i<inventory.getSlots();i++){var stack=inventory.getStackInSlot(i);if(!stack.isEmpty())totals.merge(stack.getItem(),stack.getCount(),Integer::sum);if(stack.is(Items.BREAD))food+=stack.getCount();}h.assertTrue(food==4,"Each founder receives four paid bread");}
   h.assertTrue(totals.getOrDefault(Items.STONE_AXE,0)==3&&totals.getOrDefault(Items.STONE_PICKAXE,0)==1&&totals.getOrDefault(Items.STONE_SHOVEL,0)==1&&totals.getOrDefault(Items.OAK_SAPLING,0)==16&&FoundingPlacement.remaining(l,id).isEmpty(),"Paid starter tools and saplings moved out of custody exactly once");
   for(var b:env.draft.buildings())if(b.role().equals("builder")||b.role().equals("lumberjack")){var workplace=env.home.colony().getServerBuildingManager().getBuilding(b.anchor());for(var e:FoundingSupplies.bill().keySet()){var tool=e.stack();var type=com.minecolonies.api.equipment.ModEquipmentTypes.axe.get();if(type.checkIsEquipment(tool))h.assertTrue(com.minecolonies.api.util.ItemStackUtils.hasEquipmentLevel(tool,type,0,workplace.getMaxEquipmentLevel()),"Starter axe must be usable by the initial native hut");}}
   RemoteFoundingService.advance(l,id);h.assertTrue(FoundingPlacement.remaining(l,id).isEmpty(),"Repeated founding step cannot refill supplies");pass(rows,"finite_starter_distribution");
   var interrupted=data.save(new net.minecraft.nbt.CompoundTag(),l.registryAccess());interrupted.getList("developments",10).getCompound(0).getCompound("starterDelivery").putBoolean("complete",false);h.assertTrue(RemoteDevelopmentData.load(interrupted,l.registryAccess(),l.dimension()).find(id).orElseThrow().phase()==Phase.RECOVERY_NEEDED,"Interrupted starter handoff cannot refill on reload");pass(rows,"starter_interruption_quarantined");
   if(System.getProperty("colonyhorizons.foundationSuite").startsWith("RemoteConstruction")||System.getProperty("colonyhorizons.foundationSuite").equals("MayorConstruction"))RemoteConstructionAssertions.run(h,env,owner,rows);
   if(System.getProperty("colonyhorizons.foundationSuite").equals("RemoteIllness"))RemoteIllnessAssertions.run(h,env,rows);
   if(needs)MayorNeedsAssertions.run(h,env,owner,rows);
   if(mayorSupply)MayorSupplyAssertions.run(h,env,owner,rows);
   if(System.getProperty("colonyhorizons.foundationSuite").equals("RemoteLocality"))RemoteLocalityAssertions.run(h,env,rows);
   if(System.getProperty("colonyhorizons.foundationSuite").startsWith("MayorRole"))MayorRoleAssertions.run(h,env,owner,rows);
   RemoteActivityTests.connect(owner,false);RemoteActivityService.tick(l);l.removePlayerImmediately(owner,net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);report(rows);h.succeed();
  }catch(Throwable e){fail(h,rows,e);}});
 }catch(Throwable e){fail(h,rows,e);}});}
 private static void pass(List<ProbeResult> r,String id){r.add(new ProbeResult(id,ProbeResult.Outcome.PASS,"Server approval, finite custody, native paid huts and original party"));}
 private static void verifyReload(GameTestHelper h,List<ProbeResult> rows,String phase)throws Exception{var l=h.getLevel();var data=RemoteDevelopmentData.get(l);h.assertTrue(data.all().size()==1,"No reseeding of managed founding");var r=data.all().getFirst();var owner=RemoteActivityTests.loginAtHome(l,r.owner());RemoteActivityService.tick(l);h.runAfterDelay(40,()->{try{
  h.assertTrue(data.foundingManaged(r.id())&&data.starterDelivery(r.id()).orElseThrow().complete()&&data.journey(r.id()).orElseThrow().state()==FoundingTravel.State.ARRIVED,"All managed stages persisted");var colony=com.minecolonies.api.colony.IColonyManager.getInstance().getColonyByDimension(r.draft().request().colonyId(),l.dimension());h.assertTrue(colony.getCitizenManager().getCitizens().size()==4,"Exactly four original citizens");
  for(var m:data.journey(r.id()).orElseThrow().members()){var c=colony.getCitizenManager().getCivilian(m.citizenId());h.assertTrue(c.getUUID().equals(m.entityId())&&c.getUUID().equals(data.approvedParty(r.id()).get(c.getId())),"Approved UUID persisted");c.updateEntityIfNecessary();h.assertTrue(c.getEntity().orElseThrow().blockPosition().closerThan(r.draft().request().center(),20),"Original remains remote");int food=0;for(int i=0;i<c.getInventory().getSlots();i++)if(c.getInventory().getStackInSlot(i).is(Items.BREAD))food+=c.getInventory().getStackInSlot(i).getCount();h.assertTrue(food==4,"Native paid food persists without refill");}
  if(System.getProperty("colonyhorizons.foundationSuite").startsWith("RemoteConstruction")){var entries=data.construction(r.id());h.assertTrue(entries.size()==1,"One saved construction journal");var entry=entries.values().iterator().next();var order=colony.getWorkManager().getWorkOrder(entry.nativeOrder());h.assertTrue(order!=null&&order.getTargetLevel()==entry.target()&&order.getLocation().equals(r.draft().buildings().getFirst().anchor()),"Original native order restored without reseeding");h.assertTrue(RemoteConstruction.reconcile(l,r.id()).blockers().isEmpty()&&colony.getWorkManager().getWorkOrders().size()==1,"Saved construction resumes without duplicating order");}
  if(System.getProperty("colonyhorizons.foundationSuite").startsWith("MayorSupply")){var service=dev.colonyhorizons.supply.NativeSupplyService.get(l);h.assertTrue(service.problem().isEmpty(),"Managed supply reload is readable");var routes=service.routes(r.owner());h.assertTrue(routes.size()==1,"One original managed route");var route=routes.getFirst();h.assertTrue(route.delivered()+route.cargo().getCount()==8,"Original finite cargo conserved");for(int i=0;i<4;i++)service.tick(1200);h.assertTrue(service.route(route.id()).delivered()==8&&service.route(route.id()).cargo().isEmpty(),"Original cargo delivered exactly once after process restart");h.assertTrue(dev.colonyhorizons.mayor.MayorReservations.get(l).entries().get(route.id()).dispatched().values().stream().mapToInt(Integer::intValue).sum()==8,"Original spending retained after restart");}
  RemoteFoundingService.advance(l,r.id());h.assertTrue(FoundingPlacement.remaining(l,r.id()).isEmpty(),"No refill from already spent custody");for(var b:r.draft().buildings())h.assertTrue(colony.getServerBuildingManager().getBuilding(b.anchor()).getBuildingLevel()==0,"No invented completed structures");
  if(System.getProperty("colonyhorizons.foundationSuite").startsWith("MayorRole")){var a=data.mayor(r.id()).orElseThrow();var mayor=colony.getCitizenManager().getCivilian(a.citizenId());h.assertTrue(mayor.getUUID().equals(a.entityId())&&mayor.getJob() instanceof dev.colonyhorizons.mayor.JobMayor&&dev.colonyhorizons.mayor.MayorService.available(l,r.id()),"Original native Mayor and terminal persist without reappointment: job="+mayor.getJob()+", station="+(mayor.getJob()==null?null:mayor.getJob().getBuildingPos())+", module="+(mayor.getJob()==null?null:mayor.getJob().getWorkModule())+", paid="+FoundingPlacement.isPaidAnchor(l,r.draft().buildings().getFirst())+", available="+dev.colonyhorizons.mayor.MayorService.available(l,r.id()));var station=colony.getServerBuildingManager().getBuilding(a.station());h.assertTrue(station.getFirstModuleOccurance(dev.colonyhorizons.mayor.MayorTerminalModule.class).hasAssignedCitizen(mayor)&&station.getFirstModuleOccurance(com.minecolonies.core.colony.buildings.modules.WorkerBuildingModule.class)!=station.getFirstModuleOccurance(dev.colonyhorizons.mayor.MayorTerminalModule.class)&&station.getFirstModuleOccurance(com.minecolonies.core.colony.buildings.modules.WorkerBuildingModule.class).getAssignedCitizen().stream().allMatch(c->c.getId()==r.draft().request().citizenIds().stream().filter(i->i!=r.draft().request().mayorId()).findFirst().orElseThrow()),"Separate Mayor module survives native reload; native builder may hire only the approved builder");}
  RemoteActivityTests.connect(owner,false);RemoteActivityService.tick(l);l.removePlayerImmediately(owner,net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);pass(rows,"flow_"+phase);report(rows);h.succeed();
 }catch(Throwable e){fail(h,rows,e);}});}
 private static void report(List<ProbeResult> rows)throws Exception{ProbeReport.write(Path.of(System.getProperty("colonyhorizons.probeOutput")),System.getProperty("colonyhorizons.foundationSuite","FoundingFlow"),rows);}
 private static void fail(GameTestHelper h,List<ProbeResult> r,Throwable e){try{r.add(new ProbeResult("flow_exception",ProbeResult.Outcome.FAIL,e.toString()));report(r);}catch(Exception ignored){}h.fail(e.toString());}
}
